def matrix_multiply(A, B):
    m, n = len(A), len(A[0])
    n2, p = len(B), len(B[0])
    assert n == n2

    C = [[0] * p for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def softmax(x):
    x = np.array(x)
    x_max = np.max(x)
    exp_x = np.exp(x - x_max)
    return exp_x / np.sum(exp_x)

def sigmoid(x):
    x = np.array(x)
    return 1 / (1 + np.exp(-np.clip(x, -500, 500)))

def relu(x):
    return np.maximum(0, x)

def relu_derivative(x):
    return (x > 0).astype(float)

def conv2d(image, kernel, stride=1, padding=0):
    h, w = image.shape
    kh, kw = kernel.shape

    if padding > 0:
        image = np.pad(image, padding)

    oh = (image.shape[0] - kh) // stride + 1
    ow = (image.shape[1] - kw) // stride + 1
    output = np.zeros((oh, ow))

    for i in range(oh):
        for j in range(ow):
            patch = image[i*stride:i*stride+kh, j*stride:j*stride+kw]
            output[i, j] = np.sum(patch * kernel)

    return output

def max_pool2d(image, pool_size=2, stride=None):
    if stride is None:
        stride = pool_size

    h, w = image.shape
    oh = (h - pool_size) // stride + 1
    ow = (w - pool_size) // stride + 1
    output = np.zeros((oh, ow))

    for i in range(oh):
        for j in range(ow):
            patch = image[i*stride:i*stride+pool_size, j*stride:j*stride+pool_size]
            output[i, j] = np.max(patch)

    return output

def conv_output_shape(H, W, K_h, K_w, stride=1, padding=0):
    h_out = (H - K_h + 2*padding) // stride + 1
    w_out = (W - K_w + 2*padding) // stride + 1
    return (h_out, w_out)

def pool_output_shape(H, W, pool_size, stride=None):
    if stride is None:
        stride = pool_size
    h_out = (H - pool_size) // stride + 1
    w_out = (W - pool_size) // stride + 1
    return (h_out, w_out)

def create_causal_mask(seq_len):
    mask = np.tril(np.ones((seq_len, seq_len)))
    return mask.astype(bool)

def forward(self, x):
    mean = np.mean(x, axis=-1, keepdims=True)
    var = np.var(x, axis=-1, keepdims=True)
    normalized = (x - mean) / np.sqrt(var + self.eps)
    return self.gamma * normalized + self.beta

def forward_with_cache(self, Q, K, V, use_cache=True):
    if use_cache:
        if self.kv_cache is not None:
            K_cached, V_cached = self.kv_cache
            K = np.concatenate([K_cached, K], axis=1)
            V = np.concatenate([V_cached, V], axis=1)

    # Compute attention
    output = attention(Q, K, V)

    if use_cache:
